    /\bcurl\b[^;&|]*?\s(?:-o|--output)\s+(['"]?)([^\s'"]+)\1/g,                         // curl -o file
    /\bwget\b[^;&|]*?\s(?:-O|--output-document)\s+(['"]?)([^\s'"]+)\1/g,                 // wget -O file
  ];
  for (const re of patterns) {
    for (const m of cmd.matchAll(re)) add(m[2] ?? m[1], m.index ?? 0);
