// What each step type means downstream
// ---------------------------------------------------------------------------

export type FileAccess = 'view' | 'search' | 'edit';

const FILE_ACCESS: Partial<Record<S, FileAccess>> = {
  [S.VIEW_FILE]: 'view',
  [S.GREP_SEARCH]: 'search',
  [S.FIND_BY_NAME]: 'search',
  [S.WRITE_TO_FILE]: 'edit',
  [S.REPLACE_FILE_CONTENT]: 'edit',
  [S.MULTI_REPLACE_FILE_CONTENT]: 'edit',
  [S.DELETE_FILE]: 'edit',
  [S.NOTEBOOK_EDIT]: 'edit',
};

/** How a step touches files, or null. These are drawn in the files lane, not the main track. */
export function fileAccess(stepType: S | undefined): FileAccess | null {
  return (stepType && FILE_ACCESS[stepType]) || null;
}

/** Glyph for a tool mark: a terminal for commands, a magnifier for web / code search. */
export function toolIcon(stepType: S | undefined): 'command' | 'search' | undefined {
  switch (stepType) {
    case S.RUN_COMMAND:
    case S.LIST_DIRECTORY:
      return 'command';

  const text = `(reasoning not shared by provider: ${reasoningTokens.toLocaleString()} tokens)`;
  nodes.push(createNode(`${stepId}_thinking`, TraceNodeType.THINKING, text, ReasoningStepType.PLANNER_RESPONSE, { reasoning_content: text, timestamp: step.timestamp, model }, thinkingTiming));
}

// 2. Tool Calls & Observations
if (step.tool_calls && step.tool_calls.length > 0) {
  step.tool_calls.forEach((tc, tcIdx) => {
    const tcId = `${stepId}_tc_${tcIdx}`;

    const kind = ext.toolKind(tc.tool_name) ?? inferLegacyToolKind(tc.tool_name);
    const { stepType, label: toolLabel } = classifyTool(tc, kind);

    // Find observation corresponding to this tool call
    const obs = step.observations?.find(o => o.source_call_id === tc.tool_call_id);
    const subagentRefs = ext.subagentRefs(tc.tool_call_id);
    const combinedData = { toolCall: tc, observation: obs || null, subagentRefs: subagentRefs.length ? subagentRefs : undefined };
    const startedAt = ext.toolTiming(tc.tool_call_id).started_at;
    const toolTiming = { timestamp: startedAt, completedAt: addMs(startedAt, tc.duration_ms) };

export interface ToolTiming {
  /** When the tool started running; with the schema's `duration_ms`, its span. */
  started_at?: string;
}

export const TOOL_KINDS = [
  'search.text',
  'search.files',
  'search.web',
  'search.code',
  'read.file',
  'read.url',
  'browse.directory',
  'change.file',
  'change.external',
  'file.create',
  'file.edit',
  'file.edit.multiple',
  'file.delete',
  'notebook.edit',
  'execute.command',
  'delegate.agent',
  'other',
] as const;

export type ToolKind = (typeof TOOL_KINDS)[number];

function isToolKind(value: unknown): value is ToolKind {
  return TOOL_KINDS.some(knownKind => knownKind === value);
}

/** The `metadata` keys the visualizer understands. All optional. */
export interface TraceVisMetadata {
  /**
   * Where the harness keeps the agent's own scratch files and plans, as
   * `file://` URIs or local paths. Writes there are drawn in their own lane.
   */
  artifact_dirs?: string[];

  // --- Subagents: how a child trace was launched (set on the child) ---
  parent_trace_id?: string;
  parent_tool_call_id?: string;
  subagent_role?: string;
  /** On the parent: trace ids launched by each tool call, by `tool_call_id`. */
  subagent_refs?: Record<string, string[]>;

  // --- Timing beyond the schema's single `timestamp` per step ---
  step_timing?: Record<string, StepTiming>;
  tool_timing?: Record<string, ToolTiming>;

  /**
   * Reasoning tokens per step, by `step_index`. A breakdown of the step's
   * `output_tokens`, not an addition to it (so never summed with it). Lets the
   * thinking lane show how much a model thought when the provider withholds
   * the reasoning text.
   */
  reasoning_tokens?: Record<string, number>;

  /**
   * Token totals per conversational turn, by the `step_index` of the user
   * step that opened it. For harnesses that report usage per turn but not per
   * LLM call (steps then carry no `token_usage` of their own).
   */
  turn_token_usage?: Record<string, TokenUsage>;

  /**
   * Optional normalized tool kinds, keyed by the original `tool_name`.
   * Calls keep their original names and inputs; this guides visualization.
   * Older traces without a kind are classified from their tool names.
   */
  tool_kinds?: Record<string, ToolKind>;
}

/** Typed, null-safe access to the extension keys of a record's metadata. */
export function traceExtensions(record: Pick<TraceRecord, 'metadata'>) {
  const meta: TraceVisMetadata = (record.metadata ?? {}) as TraceVisMetadata;
  const str = (v: unknown) => (typeof v === 'string' ? v : undefined);
  const rec = <T>(v: unknown): Record<string, T> =>
    v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, T>) : {};
  const stepTiming = rec<StepTiming>(meta.step_timing);
  const toolTiming = rec<ToolTiming>(meta.tool_timing);
  const reasoning = rec<number>(meta.reasoning_tokens);
  const subagentRefs = rec<string[]>(meta.subagent_refs);
  const turnUsage = rec<TokenUsage>(meta.turn_token_usage);
  return {
    artifactDirs: Array.isArray(meta.artifact_dirs) ? meta.artifact_dirs.filter((s): s is string => typeof s === 'string') : undefined,
    parentTraceId: str(meta.parent_trace_id),
    parentToolCallId: str(meta.parent_tool_call_id),
    subagentRole: str(meta.subagent_role),
    stepTiming: (stepIndex: number): StepTiming => stepTiming[String(stepIndex)] ?? {},
    toolTiming: (toolCallId: string): ToolTiming => toolTiming[toolCallId] ?? {},
    reasoningTokens: (stepIndex: number): number | undefined => {
      const n = reasoning[String(stepIndex)];
      return typeof n === 'number' && n > 0 ? n : undefined;
    },
    turnTokenUsage: (stepIndex: number): TokenUsage | undefined => turnUsage[String(stepIndex)],
    toolKind: (toolName: string): ToolKind | undefined => {
      const kind = rec<unknown>(meta.tool_kinds)[toolName];
      return isToolKind(kind) ? kind : undefined;
    },
    subagentRefs: (toolCallId: string): string[] => {
      const refs = subagentRefs[toolCallId];
      return Array.isArray(refs) ? refs.filter((s): s is string => typeof s === 'string') : [];
    },
  };
}

1. `discover_sessions()` – find your agent's log files.
2. `build_turns()` – parse them into a list of neutral *turn* dicts (user message, then the agent's messages with their reasoning and tool calls). This dict is the only contract between the layers and is documented at the top of the script.
3. `to_opentraces()` – turns the dicts into the trace format based on OpenTraces. Add source tool-name mappings in `tool_kind_for_name()` so new traces include `metadata.tool_kinds`.

Two conventions make traces light up the right lanes:

- **Tool kinds** are the visualizer's classification input. Add a `metadata.tool_kinds` map keyed by each exact original `tool_name`:

  ```json
  {
    "metadata": {
      "tool_kinds": {
        "my_file_search": "search.text",
        "my_browser": "search.web",
        "create_file": "file.create",
        "remove_file": "file.delete"
      }
    }
  }
  ```

  Use kinds such as `search.text`, `search.files`, `search.web`, `search.code`, `read.file`, `read.url`, `browse.directory`, `file.create`, `file.edit`, `file.edit.multiple`, `file.delete`, `notebook.edit`, `execute.command`, `delegate.agent`, and `other`. `change.file` and `change.external` remain accepted for compatibility, but prefer the more specific kinds for new traces. The converter should classify each source tool name once; the original `tool_name` and `input` stay unchanged. For older traces without `tool_kinds`, the visualizer infers a kind from known tool-name patterns, then renders from that normalized kind. Unknown calls use `other`.
- **File paths** should sit under a recognised input key such as `filePath`, `file_path`, `path` or `TargetFile`. For a result that touched several files, put one `File Path: /abs/path` line per file in the observation.

