def convert_tree(conversation_id: str, brain_dir: str, output_dir: str, done: dict, parent: dict = None) -> bool:
    """Converts a conversation and, recursively, every subagent it launched.

    ``done`` maps already-converted ids to ``{"path", "linked"}``. A
    conversation first seen as a root (e.g. it was among the most recent
    transcripts) is converted again when its parent turns up, so the link is
    recorded and the root-style file replaced; one converted as a child is
    never redone.
