    if prior and (prior["linked"] or parent is None):
        return True
    result = convert_transcript(conversation_id, brain_dir, output_dir, parent)
    if result is None:
        return False
    if prior and prior["path"] != result["path"] and os.path.exists(prior["path"]):
        os.remove(prior["path"])
    done[conversation_id] = {"path": result["path"], "linked": parent is not None}
    for child in result["children"]:
        convert_tree(child["id"], brain_dir, output_dir, done, parent={
            "trace_id": conversation_id,
            "tool_call_id": child["tool_call_id"],
            "role": child["role"],
